import logging
import re
import socket
import urllib
from bs4 import BeautifulSoup

logger = logging.getLogger(__name__)
WURSTBALL_RE = re.compile(r"^https?://(www\.)?wurstball\.de/[0-9]+/")


class ImageHandler:
    def __init__(self, fallback=None):
        self.fallback = fallback

    def __call__(self, metadata):
        if self.fallback is not None:
            try:
                return self.handler(metadata)
            except Exception as err:
                logger.warn("Image download failed: {}".format(err))
                return self.fallback(metadata)
        return self.handler(metadata)

    def handler(self, metadata):
        NotImplementedError("must be overridden")
        return None


class WurstballImageHandler(ImageHandler):
    def handler(self, metadata):
        if not WURSTBALL_RE.match(metadata.url):
            return None

        soup = BeautifulSoup(metadata.buf)
        img_url = soup.find(id="content-main").img["src"]

        try:
            response = urllib.request.urlopen(img_url, timeout=5)
            img_data = response.read()
        except (socket.timeout,
                urllib.error.URLError,
                urllib.error.HTTPError) as err:
            logger.warn("Could not download Wurstball image: {}".format(err))
            return None

        mime_type = response.getheader("Content-Type")

        return dict(image_mime_type=mime_type,
                    image_buffer=img_data,
                    image_url=img_url,
                    title=None,
                    description=None)

