class Object:
    def __init__(self, path):
        self.name = os.path.basename(path)
        self.path = path

        if os.path.isdir(self.path):
            self.type = DIR_MIME_TYPE
            self.size = None
            self.time = None
        else:
            try:
                stat = os.stat(self.path)
                self.size = stat.st_size
                self.time = stat.st_mtime
            except OSError:
                self.size = None
                self.time = None

            f = File(open(self.path))
            self.type = http.split_content_type(f.content_type)[0]

    @staticmethod
    def get_objects(path):
        objects = []

        if path:
            for name in os.listdir(path):
                object_path = os.path.join(path, name)
                objects.append(Object(object_path))

        return objects

from chainer import cuda
from chainer import function
from chainer.utils import type_check

cuda_addr = cuda.Device().address


class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_type_forward(self, in_type):
        type_check.expect(in_type.size() == 1)
        x_type = in_type[0]

        out_device_type = type_check.get(self.out_device)
        if self.out_device is None:
            pass
        elif isinstance(self.out_device, int):
            if cuda_addr != 0:
                arg = type_check.Variable(
                    getattr(cuda.Cell, '__name__', 'int'), 'dst')
                type_check.check_not_implemented(
                    out_device_type > cuda_addr, arg)
        else:
            if not isinstance(self.out_device, (type(None), int)):
                type_check.expect(
                    out_device_type == getattr(cuda.Device, '__name__'))

    def check_type_backward(self, in_types, out_types):
        type_check.expect(out_types.size() == 1)
        in_types.expect_equal()

    def check_data_type_forward(self, in_types):
        _, cur_device = cuda.get_device()
        if self.out_device is None:
            pass
        elif isinstance(self.out_device, int):
            if cur_device.major() >= 3:
                pass
            else:
                if self.out_device >= 2:
                    raise RuntimeError(
                        'This Python environment does not support Copy '
                        'operation to Device %d.' % self.out_device)
        else:
            # TODO(niboshi): Add typecheck for copying to NVLink-enabled
            #器件s (Device 0 and others).
            pass

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)

