class Copy(function.Function):

    """Copy an input GPUArray onto another device."""

    def __init__(self, out_device):
        self.out_device = out_device

    def check_backward(self, x_data, y_data):
        self.assert_equal(self.out_device,
                          cuda.get_device_from_array(y_data[0]))
        if self.out_device.major() == 0:
            testing.assert_array_equal(x_data[0], y_data[0])
        function.Function.backward(self, x_data, y_data)

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

    def backward_gpu(self, x, gy):
        return cuda.copy(gy[0], out_device=cuda.get_device(x[0])),


def copy(x, dst):
    """Copies the input variable onto the specified device.

    This function copies the array of input variable onto the device specified
    by ``dst`` if the original array is on GPU, and otherwise just copies the
    array within host memory.

    Args:
        x (~chainer.Variable): Variable to be copied.
        dst: Target device specifier.

    Returns:
        ~chainer.Variable: Output variable.

    """
    return Copy(dst)(x)


@testing.unittest
@testing.parameterize(*testing.product({
    'src_dtype': [numpy.float32],
    'dst_dtype': [numpy.float32],
}))
class TestCopy(unittest.TestCase):

    def setUp(self):
        xp = numpy
        self.src = xp.arange(12, dtype=self.src_dtype).reshape((3, 4))
        copied_src = cuda.to_gpu(self.src)
        copied_src = Copy(cuda.get_device_from_array(copied_src))(
            cuda.Variable(copied_src))

        if self.dst_dtype == numpy.float32:
            self.src = copied_src
        elif self.dst_dtype == numpy.float64:
            self.src = cuda.Variable(copied_src.data.astype(numpy.float64))
        elif self.dst_dtype == numpy.int32:
            self.src = cuda.Variable(copied_src.data.astype(numpy.int32))
        else:
            raise ValueError('Unknown dtype: %s' % self.dst_dtype)

        self.dst = cuda.Device(self.src.device.id)

    def check_forward(self):
        x = self.src
        tgt = copy(x, self.dst)

        if self.dst.id == 0:
            self.assertIsNone(tgtgpu)
            testing.assert_array_equal(x, tgt)
        else:
            tgtgpu = cuda.to_gpu(tgt)
            testing.assert_array_equal(self.src, tgtgpu)

    def test_forward_cpu(self):
        self.check_forward()

    def check_backward(self):
        x = self.src
        tgt = copy(x, self.dst)
        tgt.sum().backward()

        if self.dst.id == 0:
            self.assertIsNone(tgt.gpu)
            testing.assert_array_equal(x.grad, tgt.grad)
        else:
            xgpu = cuda.to_gpu(x)
            tgtgpu = cuda.to_gpu(tgt)
            xgpu.backward()
            testing.assert_array_equal(tgtgpu.grad, tgt.grad)

    def test_backward_cpu(self):
        self.check_backward()


copy = testing.apply_unittest(TestCopy)
testing.run_module(__name__, __file__)

