                cuda._device_id(gx.device_id):
            raise backend_module.CannotBackwardError(
                'Do not support backward on different device.')

    def forward_cpu(self, x):
        return x[0].copy(),

    def forward_gpu(self, x):
        return cuda.copy(x[0], out_device=self.out_device),

    def backward_cpu(self, x, gy):
        return gy[0].copy(),

